import { getProgressPhotoCategoryId, normalizeProgressPhotoCategory } from "../models/progressPhotoPoseVocabulary";

export function createProvisionalPhotoSession({ reviewId = null, captureDate, photos = [], conditions = {}, comparisonCandidates = [], captureMetadata = null, goalRelationship = null } = {}) {
  const normalizedPhotos = photos.map((photo, index) => ({
    ...normalizeProgressPhotoCategory(photo),
    active: photo.active !== false,
    order: Number.isFinite(photo.order) ? photo.order : index,
  }));
  const validation = validateProvisionalPhotoSession(normalizedPhotos);
  return {
    id: reviewId ? `provisional_session_${reviewId}` : `provisional_session_${captureDate}`,
    evidence_type: "photo_session",
    provisional: true,
    review_id: reviewId,
    observed_at: captureDate,
    photos: normalizedPhotos,
    conditions,
    captureMetadata,
    goalRelationship,
    comparison_candidates: comparisonCandidates,
    required_pose_ids: [],
    ...validation,
  };
}

export function validateProvisionalPhotoSession(photos = []) {
  const active = photos.filter((photo) => photo.active !== false);
  const poseCounts = active.reduce((counts, photo) => {
    const id = getProgressPhotoCategoryId(photo);
    counts[id] = (counts[id] ?? 0) + 1;
    return counts;
  }, {});
  const duplicate_pose_ids = Object.entries(poseCounts).filter(([id,count])=>id!=="unknown"&&count>1).map(([id])=>id);
  const missing_required_pose_ids = [];
  const unconfirmed_photo_ids = active.filter((photo) =>
    photo.identityStatus === "suggested" || photo.identityStatus === "needs_identity" || photo.userConfirmedIdentity === false
  ).map((photo) => photo.id);
  return {
    duplicate_pose_ids,
    missing_required_pose_ids,
    unconfirmed_photo_ids,
    completion_state: active.length > 0 && unconfirmed_photo_ids.length === 0 ? "complete" : "incomplete",
  };
}
